#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<int> positionsV, positionsK, positionsO;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'V') {
            positionsV.push_back(i);
        } else if (s[i] == 'K') {
            positionsK.push_back(i);
        } else {
            positionsO.push_back(i);
        }
    }

    int vCount = (int)positionsV.size();
    int kCount = (int)positionsK.size();
    int oCount = (int)positionsO.size();

    vector<vector<vector<vector<int>>>> dp(vCount + 1, vector<vector<vector<int>>>(kCount + 1, vector<vector<int>>(oCount + 1, vector<int>(2, INT_MAX))));
    vector<vector<vector<int>>> p(3, vector<vector<int>>(3, vector<int>(n, 0)));

    // Precompute p array
    for (int x = 0; x < 3; x++) {
        for (int y = 0; y < 3; y++) {
            if (x != y) {
                for (int i = 0; i < vCount; i++) {
                    for (int j = 0; j < kCount; j++) {
                        int count = 0;
                        if (x == 0 && y == 1 && positionsK[j] < positionsV[i]) count++;
                        if (x == 0 && y == 2 && positionsO[j] < positionsV[i]) count++;
                        if (x == 1 && y == 0 && positionsV[j] < positionsK[i]) count++;
                        if (x == 1 && y == 2 && positionsO[j] < positionsK[i]) count++;
                        if (x == 2 && y == 0 && positionsV[j] < positionsO[i]) count++;
                        if (x == 2 && y == 1 && positionsK[j] < positionsO[i]) count++;
                        p[x][y][i] += count;
                    }
                }
            }
        }
    }

    dp[0][0][0][1] = 0;

    for (int i = 0; i <= vCount; i++) {
        for (int j = 0; j <= kCount; j++) {
            for (int k = 0; k <= oCount; k++) {
                for (int q = 0; q < 2; q++) {
                    if (dp[i][j][k][q] != INT_MAX) {
                        if (i < vCount) {
                            int cost = dp[i][j][k][q] + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0);
                            if (cost < dp[i + 1][j][k][0]) {
                                dp[i + 1][j][k][0] = cost;
                            }
                        }
                        if (j < kCount && q == 1) {
                            int cost = dp[i][j][k][q] + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0);
                            if (cost < dp[i][j + 1][k][1]) {
                                dp[i][j + 1][k][1] = cost;
                            }
                        }
                        if (k < oCount) {
                            int cost = dp[i][j][k][q] + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0);
                            if (cost < dp[i][j][k + 1][1]) {
                                dp[i][j][k + 1][1] = cost;
                            }
                        }
                    }
                }
            }
        }
    }

    int answer = min(dp[vCount][kCount][oCount][0], dp[vCount][kCount][oCount][1]);
    cout << answer << "\n";

    return 0;
}
